const inputItem = $input.first();

if (!inputItem?.binary) {
  throw new Error("No se encontraron datos binarios en la entrada del nodo de activación.");
}

const [binaryKey] = Object.keys(inputItem.binary);
if (!binaryKey) {
  throw new Error("El objeto binario está vacío o mal estructurado.");
}

let parsedData;
try {
  const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  const rawString = binaryBuffer.toString('utf-8');
  parsedData = JSON.parse(rawString);
} catch (error) {
  throw new Error(`Fallo crítico al parsear el archivo binario a JSON: ${error.message}`);
}

const itemsToProcess = Array.isArray(parsedData) ? parsedData : [parsedData];

return itemsToProcess.map(({ id_code_combination, icf_code, icf_name }) => ({
  json: {
    id_code_combination,
    icf_codes: icf_code,
    icf_name: icf_name ?? null,
  }
}));

const extractRawText = (json) => {
  // Ahora cubre la estructura nativa de Gemini y el output de LangChain
  return json?.content?.parts?.[0]?.text || 
         json?.text ||
         json?.response || 
         json?.choices?.[0]?.message?.content || 
         json?.output || 
         json?.message;
};

const cleanMarkdownJSON = (text) => {
  const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  return match ? match[1] : text;
};

const parseLLMData = (rawText) => {
  const cleanText = cleanMarkdownJSON(rawText);
  return JSON.parse(cleanText.trim()); // Dejamos que el try-catch principal maneje el error
};

const formatClinicalHistories = (parsedData, baseData) => {
  const histories = Array.isArray(parsedData) 
      ? parsedData 
      : (parsedData.clinical_object || parsedData.historias_clinicas || [parsedData]);

  if (!Array.isArray(histories)) return [];

  return histories.map((history, index) => {
    // Fallback seguro: garantizamos que sea un string
    const textContent = typeof history === 'string' 
      ? history 
      : (history.clinical_text || JSON.stringify(history));

    return {
      id_code_combination: baseData.id_code_combination,
      icf_codes: baseData.icf_codes,
      icf_name: baseData.icf_name,
      id_clinical_text: `${baseData.id_code_combination}_${index + 1}`,
      clinical_text: textContent
    };
  });
};

const originalData = $('doc_to_json1').all();
const currentInputs = $input.all();

const finalResults = currentInputs.flatMap((item, index) => {
  try {
    const rawText = extractRawText(item.json);

    if (!rawText) {
      throw new Error("Missing text variable in LLM response. Estructura recibida: " + JSON.stringify(Object.keys(item.json)));
    }

    const aiData = parseLLMData(rawText);
    const baseData = originalData[index]?.json || {}; // Previene error si el índice no coincide
    const formattedHistories = formatClinicalHistories(aiData, baseData);

    return formattedHistories.map(history => ({
      json: history
    }));

  } catch (error) {
    return [{
      json: {
        _processing_error: true,
        error_message: error.message,
        original_index: index,
        raw_data: item.json
      }
    }];
  }
});

return finalResults;

for (const item of $input.all()) {
  item.json = {
    icf_codes: item.json.icf_codes,
    icf_name: item.json.icf_name,
  };
}

return $input.all();;

